import{_ as a,o as e,c as o,ag as s}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md"}'),r={name:"features/dashboard.md"};function i(n,t,d,l,h,c){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The dashboard provides an at-a-glance overview of your entire Claude Code configuration with 12 information cards organized in a responsive grid.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>When you open Claude Deck, the dashboard aggregates data from 12 API endpoints in parallel and displays:</p><ul><li><strong>Projects</strong> — number of tracked project directories</li><li><strong>MCP Servers</strong> — configured server count</li><li><strong>Commands</strong> — available slash commands</li><li><strong>Plugins</strong> — installed plugins</li><li><strong>Hooks</strong> — automation hooks</li><li><strong>Permissions</strong> — total permission rules</li><li><strong>Agents</strong> — custom agents across all scopes</li><li><strong>Skills</strong> — available skills</li><li><strong>Output Styles</strong> — custom output formats</li><li><strong>Sessions</strong> — total count with today/this week breakdown and most active project</li><li><strong>Plans</strong> — execution plan count</li><li><strong>Context Window</strong> — highest context usage across active sessions with a color-coded progress bar</li></ul><p>A <strong>Quick Status</strong> card at the bottom shows settings key count and allow/deny rule breakdown.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="viewing-data" tabindex="-1">Viewing Data <a class="header-anchor" href="#viewing-data" aria-label="Permalink to &quot;Viewing Data&quot;">​</a></h3><p>All cards update together. The dashboard shows project-scoped data for the currently selected project — switch projects using the sidebar selector.</p><h3 id="context-window-indicator" tabindex="-1">Context Window Indicator <a class="header-anchor" href="#context-window-indicator" aria-label="Permalink to &quot;Context Window Indicator&quot;">​</a></h3><p>The context window card shows the highest context usage percentage across all active Claude Code sessions:</p><table tabindex="0"><thead><tr><th>Color</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td>Green</td><td>0–49%</td><td>Plenty of room</td></tr><tr><td>Yellow</td><td>50–79%</td><td>Getting used</td></tr><tr><td>Orange</td><td>80–94%</td><td>Running low</td></tr><tr><td>Red</td><td>95–100%</td><td>Nearly full</td></tr></tbody></table><h3 id="refreshing" tabindex="-1">Refreshing <a class="header-anchor" href="#refreshing" aria-label="Permalink to &quot;Refreshing&quot;">​</a></h3><p>Click the <strong>refresh button</strong> in the top-right corner to reload all data. The dashboard caches data between page navigations — navigating away and back shows cached data instantly without a loading flash.</p><p>A relative timestamp (&quot;Updated 2m ago&quot;) next to the refresh button shows when data was last fetched.</p><h3 id="navigation-links" tabindex="-1">Navigation Links <a class="header-anchor" href="#navigation-links" aria-label="Permalink to &quot;Navigation Links&quot;">​</a></h3><p>Several cards include links to jump to their full page:</p><ul><li>&quot;View all sessions →&quot; on the Sessions card</li><li>&quot;View context →&quot; on the Context Window card</li><li>&quot;View all plans →&quot; on the Plans card</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The dashboard has no dedicated configuration. It reads data from all other features. The active project (set via sidebar) determines the scope for MCP servers, commands, hooks, and permissions.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Data is cached</strong> — switching pages doesn&#39;t trigger a re-fetch. Click refresh for fresh data.</li><li><strong>Project switching</strong> automatically re-fetches dashboard data for the new project.</li><li><strong>First visit</strong> shows a loading skeleton while data loads. Subsequent visits show cached data.</li></ul>',22)])])}const p=a(r,[["render",i]]);export{u as __pageData,p as default};
